-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.is_allowed_email(email text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(
    array_length(string_to_array(lower(trim(email)), '@'), 1) = 2
      and split_part(lower(trim(email)), '@', 1) <> ''
      and split_part(lower(trim(email)), '@', 2) = 'ug.uchile.cl',
    false);
$function$;

grant execute on function public.is_allowed_email(email text) to anon;
grant execute on function public.is_allowed_email(email text) to authenticated;
grant execute on function public.is_allowed_email(email text) to public;
grant execute on function public.is_allowed_email(email text) to service_role;
